def task(robot):
    cans = robot.look()
    if not cans:
        robot.say("Sorry, there are no drinks here.")
        return

    colors = set(can['colour'] for can in cans)
    robot.say("What colour would you like?")

    guest_choice = robot.listen()

    if guest_choice in colors:
        target_colour = guest_choice
        for can in cans:
            if can['colour'] == target_colour:
                robot.pick(can['id'])
                robot.say(f"Here is your {target_colour} drink.")
                robot.give()
                robot.place("table")
                return
    else:
        robot.say("Sorry, I don't have a drink of that colour.")

